## Why This Is Asked

Tests knowledge of two classic sorts, practical optimization, and memory trade-offs. A hybrid approach reveals ability to tune algorithms for real data patterns.

## Key Concepts
- Hybrid sorting threshold and when it helps
- Stability via merge vs insertion behavior
- Space usage with a single auxiliary buffer

## Code Example
```javascript
function sortBatch(arr) {
  const n = arr.length;
  const buf = new Array(n);
  function insertionSort(a, left, right) {
    for (let i = left + 1; i <= right; i++) {
      const key = a[i];
      let j = i - 1;
      while (j >= left && a[j] > key) {
        a[j + 1] = a[j];
        j--;
      }
      a[j + 1] = key;
    }
  }
  function merge(left, mid, right) {
    let i = left, j = mid + 1, k = left;
    while (i <= mid && j <= right) {
      if (arr[i] <= arr[j]) buf[k++] = arr[i++];
      else buf[k++] = arr[j++];
    }
    while (i <= mid) buf[k++] = arr[i++];
    while (j <= right) buf[k++] = arr[j++];
    for (let t = left; t <= right; t++) arr[t] = buf[t];
  }
  function sort(l, r) {
    if (l >= r) return;
    if (r - l + 1 <= 16) {
      insertionSort(arr, l, r);
    } else {
      const m = Math.floor((l + r) / 2);
      sort(l, m);
      sort(m + 1, r);
      merge(l, m, r);
    }
  }
  sort(0, n - 1);
}
```

## Why This Is Asked

Tests ability to design in-place sorting algorithms, understand stability, and reason about trade-offs between time and memory in constrained environments.

## Key Concepts

- In-place merging
- Stability
- Time/space complexity
- Rotation-based merging

## Code Example

```javascript
function inPlaceMerge(arr, left, mid, right) {
  let i = left, j = mid + 1;
  while (i <= mid && j <= right) {
    if (arr[i] <= arr[j]) { i++; continue; }
    const tmp = arr[j];
    for (let k = j; k > i; k--) arr[k] = arr[k - 1];
    arr[i] = tmp;
    i++; mid++; j++;
  }
}

function inPlaceMergeSort(arr, left = 0, right = arr.length - 1) {
  if (left >= right) return;
  const mid = Math.floor((left + right) / 2);
  inPlaceMergeSort(arr, left, mid);
  inPlaceMergeSort(arr, mid + 1, right);
  inPlaceMerge(arr, left, mid, right);
}
```

